// Creates a MT_to_review custom translation status in the projects that have
// none, so the 471 Thai style fixes can be flagged for Natcha consistently.
//
// Checked 2026-08-27 via GET /projects/{id}/custom_translation_statuses.
// Projects NOT in this list already have a usable status and are left alone:
//   Personality.co           29251  MT_to_review
//   QRcreate                 25875  MT_to_review
//   My QR Code               25140  MT_to_review
//   Realchecker (FE)         29175  MT_TO_REVIEW   (different case, same intent)
//   PDF Editor (BE- emails)  29306  MT_TO_REVIEW   (different case, same intent)
// Reusing those avoids creating near-duplicate statuses in the same project.
//
// Note: custom statuses must be enabled per project (Settings -> Translation).
// Where the feature is off, Lokalise answers 409, not 403.
const TITLE = 'MT_to_review';
const COLOR = '#ff9f1a';   // matches the existing MT_to_review statuses

const TARGETS = [
  ['7497898368b56f1d07ee46.54496723', 'MyImage - html/legal pages', 69],
  ['901014606819db6d0bc999.26230201', 'Mobitrace - html/legal pages', 60],
  ['18564477693fc9bba4cec8.54789459', 'My QR Code html', 32],
  ['46919453689d5d729a1e70.59972091', 'PDF Editor - html/legal pages', 21],
  ['9933660066825e9a8005c8.58526829', 'Personality - Members area content', 2],
  ['9274956467e3e224807498.79791832', 'Mobitrace - backend/emails', 2],
  ['3070657967b5854be32cb1.65162854', 'My Image', 4],
  ['1286096867dbf31146afc5.54950617', 'PDF Editor', 1]
];

return TARGETS.map(function (t) {
  return { json: {
    project_id: t[0], project_name: t[1], fixes_pending: t[2],
    title: TITLE, color: COLOR,
    url: 'https://api.lokalise.com/api2/projects/' + t[0] + '/custom_translation_statuses',
    payload: { title: TITLE, color: COLOR }
  } };
});

// neverError is on here so a 409 (feature disabled) is reported rather than
// aborting the other projects. Every response is inspected explicitly.
const plan = $('Plan').all().map(function (x) { return x.json; });
const items = $input.all();

const results = [];
let created = 0, failed = 0;

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const cfg = plan[i] || {};
  const status = r.statusCode;
  const body = (r.body !== undefined) ? r.body : r;
  const st = (body && body.custom_translation_status) || null;

  const ok = status === 200 || status === 201;
  if (ok && st && st.status_id) created++; else failed++;

  results.push({
    project: cfg.project_name || cfg.project_id,
    project_id: cfg.project_id,
    fixes_pending: cfg.fixes_pending,
    http_status: status,
    status_id: st ? st.status_id : null,
    title: st ? st.title : null,
    error: ok ? null : (typeof body === 'string' ? body.slice(0, 300) : JSON.stringify(body).slice(0, 300))
  });
}

const blocked = results.filter(function (x) { return !x.status_id; });

return [{ json: {
  attempted: results.length, created: created, failed: failed,
  strings_unblocked: results.filter(function (x) { return x.status_id; })
    .reduce(function (a, x) { return a + (x.fixes_pending || 0); }, 0),
  strings_still_blocked: blocked.reduce(function (a, x) { return a + (x.fixes_pending || 0); }, 0),
  blocked_projects: blocked,
  status_map: results.filter(function (x) { return x.status_id; })
    .map(function (x) { return { project_id: x.project_id, project: x.project, status_id: x.status_id }; }),
  results: results } }];
